package com.bank.logcmp.service;

import java.util.logging.Logger;

// Longest Common Subsequence with two rolling rows for O(n) space.
public class LogComparisonService {
    private static final Logger log = Logger.getLogger(LogComparisonService.class.getName());

    public int longestCommonLength(String logA, String logB) {
        int m = logA.length(), n = logB.length();
        int[] prev = new int[n + 1];                       // previous row
        int[] cur = new int[n + 1];                        // current row
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (logA.charAt(i - 1) == logB.charAt(j - 1)) {
                    cur[j] = prev[j - 1] + 1;              // match → diagonal + 1
                } else {
                    cur[j] = Math.max(prev[j], cur[j - 1]); // drop one side
                }
            }
            int[] tmp = prev; prev = cur; cur = tmp;        // roll rows, reuse the array
        }
        final int result = prev[n];                        // answer is in prev after the swap
        log.info(() -> "Longest common entry length = " + result);
        return prev[n];
    }
}
