package com.bank.logcmp;

import com.bank.logcmp.service.LogComparisonService;
import java.util.logging.Logger;

public class LogComparisonApplication {
    private static final Logger log = Logger.getLogger(LogComparisonApplication.class.getName());

    public static void main(String[] args) {
        LogComparisonService service = new LogComparisonService();
        // Each letter encodes a transaction type in the two log versions.
        int len = service.longestCommonLength("ABCBDAB", "BDCAB");
        log.info(() -> "Final common backbone length = " + len);
    }
}
